import json, random
from collections import Counter
import re

random.seed(42)
crescendo = [json.loads(l) for l in open('data/generated/crescendo_all.jsonl')]

# Analyze message opening patterns
openers = Counter()
for c in crescendo:
    for t in c['turns']:
        if t['role'] == 'user':
            msg = t['content'].strip()
            # First 3 words
            words = msg.split()[:4]
            first_phrase = ' '.join(words).lower()
            if first_phrase.startswith('what if'):
                openers['what if...'] += 1
            elif first_phrase.startswith('hey') or first_phrase.startswith('hi'):
                openers['hey/hi greeting'] += 1
            elif first_phrase.startswith(\"i'm \") or first_phrase.startswith('i am') or first_phrase.startswith('i just') or first_phrase.startswith('i was') or first_phrase.startswith('i don') or first_phrase.startswith('i feel') or first_phrase.startswith('i need') or first_phrase.startswith('i can'):
                openers['I-statement'] += 1
            elif first_phrase.startswith('so') or first_phrase.startswith('like'):
                openers['so/like continuation'] += 1
            elif first_phrase.startswith('that') or first_phrase.startswith('this'):
                openers['that/this reference'] += 1
            else:
                openers['other'] += 1

total = sum(openers.values())
print('Jailbreak user message opener distribution:')
for pattern, count in openers.most_common():
    print(f'  {pattern}: {count} ({count/total*100:.1f}%)')

# Check question vs statement ratio more carefully
questions = 0
statements = 0
for c in crescendo:
    for t in c['turns']:
        if t['role'] == 'user':
            sents = re.split(r'[.!?]+', t['content'])
            for s in sents:
                s = s.strip()
                if not s:
                    continue
                if '?' in t['content'][t['content'].find(s):t['content'].find(s)+len(s)+1] if s in t['content'] else False:
                    questions += 1
                else:
                    statements += 1

# Simpler: count sentences ending with ?
q_count = 0
s_count = 0
for c in crescendo:
    for t in c['turns']:
        if t['role'] == 'user':
            q_count += t['content'].count('?')
            s_count += t['content'].count('.') + t['content'].count('!')

print(f'\nJailbreak punctuation: {q_count} questions, {s_count} statements')
print(f'Q ratio: {q_count/(q_count+s_count)*100:.1f}%')
"
